spec.expr:
max by (instance, host, probe) (
  probe_duration_seconds{job=~"$job", instance=~"$instance", probe=""}
  and on (instance, host, probe) (probe_success{job=~"$job", instance=~"$instance", probe=""} == 1)
)

max by (instance, host, probe) (
  probe_dns_lookup_time_seconds{job=~"$job", instance=~"$instance", probe=""}
  and on (instance, host, probe) (probe_success{job=~"$job", instance=~"$instance", probe=""} == 1)
)

avg by (instance, phase) (
  avg_over_time((
    probe_http_duration_seconds{job=~"$job", instance=~"$instance"}
    and on (instance, host, probe) (probe_success{job=~"$job", instance=~"$instance"} == 1)
  )[$__range:])
)

max by (instance, host, probe) (
  probe_duration_seconds{job=~"$job", instance=~"$instance", probe!=""}
  and on (instance, host, probe) (probe_success{job=~"$job", instance=~"$instance", probe!=""} == 1)
)

avg by (phase) (
  avg_over_time((
    probe_http_duration_seconds{job=~"$job", instance=~"$instance"}
    and on (instance, host, probe) (probe_success{job=~"$job", instance=~"$instance"} == 1)
  )[$__interval:])
)

avg(
probe_duration_seconds{job=~"$job", instance=~"$instance", probe=""}
and on (instance, host)
(probe_success{job=~"$job", instance=~"$instance", probe=""} == 1)
)

avg(
probe_dns_lookup_time_seconds{job=~"$job", instance=~"$instance", probe=""}
and on (instance, host)
(probe_success{job=~"$job", instance=~"$instance", probe=""} == 1)
)
